# Posts published through /api/blog (scheduled runs) live as JSON in tools/blog_posts/. Merged in here, newest first.
import glob as _glob, json as _json, os as _os
for _f in sorted(_glob.glob(_os.path.join(_os.path.dirname(_os.path.abspath(__file__)), 'blog_posts', '*.json'))):
    _p = _json.load(open(_f))
    _p['body'] = [tuple(x) for x in _p['body']]
    POSTS.append(_p)
POSTS.sort(key=lambda p: p['date'], reverse=True)
